pub fn greet(users: &[User]) -> Vec<String> { users.iter().map(format_user).collect() }
pub fn to_json(users: &[User]) -> String {
    let inner = users
        .iter()
        .map(|u| format!(
            "{{\"name\":\"{}\",\"age\":{}}}",
            u.name.replace('\\', "\\\\").replace('"', "\\\""),
            u.age
        ))
        .collect::<Vec<_>>()
        .join(",");
    format!("[{}]", inner)
}

#[cfg(test)] mod tests { use super::*;
  #[test] fn t_greet() { let u = User{name:"Ali".into(),age:25}; assert_eq!(greet(&[u])[0], "Ali (25)"); }
  #[test] fn t_to_json() {
    let users = vec![User{name:"Ali".into(),age:25}];
    assert_eq!(to_json(&users), r#"[{"name":"Ali","age":25}]"#);
  }
  #[test] fn t_to_json_empty() {
    let users: Vec<User> = vec![];
    assert_eq!(to_json(&users), "[]");
  }
}

